/** Map geocoder subdivision (ISO key or title) onto Start province/state labels. */
function provinceFromAddress(liveId, stateTerritory) {
  const raw = (stateTerritory || '').trim();
  if (!raw) return '';
  const list = PROVINCES[liveId];
  if (list) {
    const exact = list.find((p) => p.toLowerCase() === raw.toLowerCase());
    if (exact) return exact;
  }
  const opts = STATES_BY_COUNTRY[(liveId || '').toUpperCase()] || [];
  const byKey = opts.find((o) => o.key.toLowerCase() === raw.toLowerCase());
  if (byKey) {
    if (list && list.includes(byKey.title)) return byKey.title;
    return byKey.title;
  }
  const byTitle = opts.find((o) => o.title.toLowerCase() === raw.toLowerCase());
  if (byTitle) {
    if (list && list.includes(byTitle.title)) return byTitle.title;
    return byTitle.title;
  }
  return raw;
}

